public CharBuffer Compact()
{
    // Copy the remaining characters to the beginning of the buffer
    Array.Copy(
        backingArray,            // source array
        position + offset,       // source index
        backingArray,            // destination array
        offset,                  // destination index
        Remaining());            // number of elements to copy

    // Update buffer state to reflect the compacted data
    position = limit - position;
    limit    = capacity;
    mark     = UNSET_MARK;

    return this;
}
