public static long PopIntersect(long[] arr1, long[] arr2, int wordOffset, int numWords)
{
    long popCount = 0;
    int end = wordOffset + numWords;
    for (int i = wordOffset; i < end; ++i)
    {
        popCount += (long)BitOperations.PopCount((ulong)(arr1[i] & arr2[i]));
    }
    return popCount;
}
