public static long PopAndNot(long[] arr1, long[] arr2, int wordOffset, int numWords)
{
    long popCount = 0;
    for (int i = wordOffset, end = wordOffset + numWords; i < end; ++i)
    {
        // Compute a & ~b and count the set bits
        ulong bits = (ulong)(arr1[i] & ~arr2[i]);
        popCount += (long)BitOperations.PopCount(bits);
    }
    return popCount;
}
