public static int Tagger(byte[] b, int ptr)
{
    int sz = b.Length;
    if (ptr == 0) ptr += 48;

    while (ptr < sz)
    {
        if (b[ptr] == (byte)'\n')
            return -1;

        int m = Match(b, ptr, Tagger); // assumes Match expects a delegate matching this signature
        if (m >= 0)
            return m;

        ptr = NextLF(b, ptr);
    }

    return -1;
}
