public void FreeBefore(int pos)
{
    int toFree = count - (nextPos - pos);
    System.Diagnostics.Debug.Assert(toFree >= 0);
    System.Diagnostics.Debug.Assert(toFree <= count);
    int index = nextWrite - count;
    if (index < 0)
    {
