```csharp
using System.IO;

public static class UnicodeStringWriter
{
    public static void WriteUnicodeString(BinaryWriter writer, string value)
    {
        // Number of characters in the string
        int nChars = value.Length;

        // Write the length as a 16‑bit little‑endian value
        writer.Write((short)nChars);

        // Determine whether the string needs 16‑bit Unicode representation
        bool is16Bit = HasMultibyte(value);

        // Write the flag byte (0x01 for 16‑bit, 0x00 for compressed)
        writer.Write((byte)(is16Bit ? 0x01 : 0x00));

        // Write the actual string data in the appropriate format
        if (is16Bit)
        {
            PutUnicodeLE(value, writer);
        }
        else
        {
            PutCompressedUnicode(value, writer);
        }
    }

    // Placeholder for the original Java methods – implement as needed
    private static bool HasMultibyte(string s)
    {
        // Returns true if any character requires more than one byte (i.e., > 0xFF)
        foreach (char c in s)
        {
            if (c > 0xFF) return true;
        }
        return false;
    }

    private static void PutUnicodeLE(string s, BinaryWriter writer)
    {
        // Write each character as little‑endian UTF‑16 (2 bytes per char)
        foreach (char c in s)
        {
            writer.Write((ushort)c);
        }
    }

    private static void PutCompressedUnicode(string s, BinaryWriter writer)
    {
        // Write each character as a single byte (only low 8 bits)
        foreach (char c in s)
        {
            writer.Write((byte)(c & 0xFF));
        }
    }
}
