public float GetTokenScore()
{
    // Update the current position using the position increment attribute
    position += posIncAtt.PositionIncrement;

    // Get the term text from the term attribute
    string termText = termAtt.ToString();

    // Look up the weighted span term for this text
    WeightedSpanTerm weightedSpanTerm;
    if ((weightedSpanTerm = fieldWeightedSpanTerms.GetValueOrDefault(termText)) == null)
        return 0f;

    // If the term is position‑sensitive, make sure the current position is valid
    if (weightedSpanTerm.PositionSensitive && !weightedSpanTerm.CheckPosition(position))
        return 0f;

    // Retrieve the weight (score) of the term
    float score = weightedSpanTerm.Weight;

    // Add the score to the total only once per distinct term
    if (!foundTerms.Contains(termText))
    {
        totalScore += score;
        foundTerms.Add(termText);
    }

    return score;
}
