public void Write(byte[] b, int off, int len)
{
    // Bounds checking – matches Java's IndexOutOfBoundsException
    if ((off < 0) || (off > b.Length) || (len < 0) ||
        ((off + len) > b.Length) || ((off + len) < 0))
    {
        throw new IndexOutOfRangeException();
    }
    else if (len == 0)
    {
        return;
    }

    do
    {
        CreateBlockIfNeeded();                       // same as Java's createBlockIfNeeded()
        int writeBytes = Math.Min(buffer.Remaining, len);
        buffer.Put(b, off, writeBytes);               // assumes a Put method analogous to Java's ByteBuffer.put
        off += writeBytes;
        len -= writeBytes;
    } while (len > 0);
}
