public List<MatchingDocs> GetMatchingDocs()
{
    // Call the base implementation
    List<MatchingDocs> matchingDocs = base.GetMatchingDocs();

    // Calculate total hits if needed
    if (totalHits == NOT_CALCULATED)
    {
        totalHits = 0;
        foreach (MatchingDocs md in matchingDocs)
        {
            totalHits += md.TotalHits;   // assuming MatchingDocs exposes a TotalHits property
        }
    }

    // If the total number of hits is within the sample size, just return the full list
    if (totalHits <= sampleSize)
    {
        return matchingDocs;
    }

    // Otherwise create (once) and return the sampled list
    if (sampledDocs == null)
    {
        samplingRate = (1.0 * sampleSize) / totalHits;
        sampledDocs = CreateSampledDocs(matchingDocs);   // assumes a method returning List<MatchingDocs>
    }

    return sampledDocs;
}
