public static CoderResult UnmappableForLength(int length)
{
    lock (typeof(CoderResult)) // static synchronized equivalent
    {
        if (length > 0)
        {
            int key = length;
            lock (_unmappableErrors)
            {
                CoderResult r;
                if (!_unmappableErrors.TryGetValue(key, out r))
