    if (len > int.MaxValue)
        throw new OutOfMemoryException(
            JGitText.Get().LengthExceedsMaximumArraySize);

    byte[] result = new byte[(int)len];
    int outPtr = 0;

    foreach (Block b in blocks)
    {
