using System;
using System.Collections.Generic;

public static class TransportFactory
{
    // Assume this field is defined elsewhere in the class.
    // It holds weak references to the available TransportProtocol instances.
    private static readonly List<WeakReference<TransportProtocol>> protocols = new();

    public static Transport Open(URIish uri)
    {
        // Iterate backwards so we can safely remove dead references.
        for (int i = protocols.Count - 1; i >= 0; i--)
        {
            var weakRef = protocols[i];

            // Try to retrieve the target object from the weak reference.
            if (!weakRef.TryGetTarget(out TransportProtocol proto) || proto == null)
            {
                // The referenced protocol has been garbage‑collected; remove the reference.
                protocols.RemoveAt(i);
                continue;
            }

            // If the protocol can handle the given URI, delegate the opening to it.
            if (proto.CanHandle(uri, null, null))
                return proto.Open(uri);
        }

        // No protocol could handle the URI – throw the appropriate exception.
        throw new NotSupportedException(
            string.Format(JGitText.Get().URINotSupported, uri));
    }
}
