public static int Update(int hash, int value)
{
    const int c1 = unchecked((int)0xCC9E2D51);
    const int c2 = unchecked((int)0x1B873593);
    const int r1 = 15;
    const int r2 = 13;
    const int m  = 5;
    const int n  = unchecked((int)0xE6546B64);

    unchecked
    {
        int k = value;
        k = k * c1;
        k = (k << r1) | (int)((uint)k >> (32 - r1));
        k = k * c2;

        hash ^= k;
        hash = (hash << r2) | (int)((uint)hash >> (32 - r2));
        hash = hash * m + n;
    }

    return hash;
