public DoubleRange(string label, double minIn, bool minInclusive,
                   double maxIn, bool maxInclusive)
    : base(label)
{
    if (double.IsNaN(minIn))
        throw new ArgumentException("min cannot be NaN");

    if (!minInclusive)
        minIn = Math.BitIncrement(minIn);   // equivalent to Java's Math.nextUp

    if (double.IsNaN(maxIn))
        throw new ArgumentException("max cannot be NaN");

    if (!maxInclusive)
        maxIn = Math.BitDecrement(maxIn);   // equivalent to Java's Math.nextAfter(..., Double.NEGATIVE_INFINITY)

    if (minIn > maxIn)
        FailNoMatch();   // assumes a method analogous to Java's failNoMatch()

    this.min = minIn;
    this.max = maxIn;
}
