public RecordInputStream CreateDecryptingStream(Stream original)
{
    // Get the password that should be used for decryption
    string userPassword = Biff8EncryptionKey.GetCurrentUserPassword();
    if (userPassword == null)
    {
        userPassword = Decryptor.DEFAULT_PASSWORD;
    }

    // Retrieve the encryption information stored in the file‑pass record
    EncryptionInfo info = _filePassRec.GetEncryptionInfo();

    try
    {
        // Verify that the supplied password is correct for the document
        if (!info.Decryptor.VerifyPassword(userPassword))
        {
            // Build an informative message – indicate whether the default or a
            // user‑supplied password was used.
            string pwdKind = Decryptor.DEFAULT_PASSWORD.Equals(userPassword)
                ? "Default"
                : "Supplied";

            throw new EncryptedDocumentException(
                $"{pwdKind} password is invalid for salt/verifier/verifierHash");
        }
    }
    // In POI this catches GeneralSecurityException; in .NET we catch the base
    // exception type that the VerifyPassword method may throw (e.g. CryptographicException)
    catch (Exception e)
    {
        throw new EncryptedDocumentException(e);
    }

    // Return a RecordInputStream that will automatically decrypt data read from
    // the supplied original stream.
    return new RecordInputStream(original, info, _initialRecordsSize);
}
