public ICollection<RevCommit> Call()
{
    CheckCallable();

    try
    {
        if (repo.ExactRef(Constants.R_STASH) == null)
            return Enumerable.Empty<RevCommit>();
    }
    catch (IOException e)
    {
        throw new InvalidReferenceNameException(
            string.Format(JGitText.Get().CannotRead, Constants.R_STASH), e);
    }

    var refLog = new ReflogCommand(repo);
    refLog.SetRef(Constants.R_STASH);
    var stashEntries = refLog.Call();

    if (!stashEntries.Any())
        return Enumerable.Empty<RevCommit>();

    var stashCommits = new List<RevCommit>(stashEntries.Count());

    using (var walk = new RevWalk(repo))
    {
        foreach (var entry in stashEntries)
        {
            try
            {
                stashCommits.Add(walk.ParseCommit(entry.NewId));
            }
            catch (IOException e)
            {
                throw new JGitInternalException(
                    string.Format(JGitText.Get().CannotReadCommit, entry.NewId), e);
            }
        }
    }

    return stashCommits;
}
