```csharp
public static void RegisterFunction(string name, Function func)
{
    // Look up the metadata for the function name
    FunctionMetadata metaData = FunctionMetadataRegistry.GetFunctionByName(name);

    if (metaData == null)
    {
        // The name is not known to POI – it might be an Analysis‑ToolPak function
        if (AnalysisToolPak.IsATPFunction(name))
        {
            throw new ArgumentException(
                $"{name} is a function from the Excel Analysis Toolpack. " +
                "Use AnalysisToolpack.RegisterFunction(string name, FreeRefFunction func) instead.");
        }

        throw new ArgumentException($"Unknown function: {name}");
    }

    // Index of the function implementation in the internal array
    int idx = metaData.Index;

    // If the slot currently contains a placeholder, replace it with the supplied implementation
    if (functions[idx] is NotImplementedFunction)
    {
        functions[idx] = func;
    }
    else
    {
        // POI already provides an implementation – do not allow overriding it
        throw new ArgumentException(
            $"POI already implements {name}. You cannot override POI's implementations of Excel functions");
    }
}
