public void Reset(bool zeroFillBuffers, bool reuseFirst)
{
    if (bufferUpto != -1)
    {
        if (zeroFillBuffers)
        {
            // Fill all fully‑used buffers with zeros
            for (int i = 0; i < bufferUpto; i++)
            {
                Array.Fill(buffers[i], 0);
            }

            // Fill the partially‑used buffer up to intUpto with zeros
            Array.Fill(buffers[bufferUpto], 0, 0, intUpto);
        }

        // Recycle buffers that are no longer needed
        if (bufferUpto > 0 || !reuseFirst)
        {
            int offset = reuseFirst ? 1 : 0;
            allocator.RecycleIntBlocks(buffers, offset, 1 + bufferUpto);
            Array.Fill(buffers, null, offset, bufferUpto + 1 - offset);
        }

        // Reset state for reuse or for a fresh start
        if (reuseFirst)
        {
            bufferUpto = 0;
            intUpto   = 0;
            intOffset = 0;
            buffer    = buffers[0];
        }
        else
        {
            bufferUpto = -1;
            intUpto   = INT_BLOCK_SIZE;
            intOffset = -INT_BLOCK_SIZE;
            buffer    = null;
        }
    }
}
