public static bool? CoerceValueToBoolean(ValueEval ve, bool stringsAreBlanks)
{
    if (ve == null || ve == BlankEval.Instance)
    {
        return null;
    }

    if (ve is BoolEval be)
    {
        return be.GetBooleanValue();
    }

    if (ve is StringEval se)
    {
        if (stringsAreBlanks)
        {
            return null;
        }

        string str = se.GetStringValue();
        if (string.Equals(str, "true", StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }
        if (string.Equals(str, "false", StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }
        throw new EvaluationException(ErrorEval.VALUE_INVALID);
    }

    if (ve is NumericValueEval ne)
    {
        double d = ne.GetNumberValue();
        if (double.IsNaN(d))
        {
            throw new EvaluationException(ErrorEval.VALUE_INVALID);
        }
        return d != 0;
    }

    if (ve is ErrorEval ee)
    {
        throw new EvaluationException(ee);
    }

    throw new Exception($"Unexpected eval ({ve.GetType().Name})");
}
