public long Skip(long byteCount)
{
    if (byteCount < 0)
        throw new ArgumentException($"byteCount < 0: {byteCount}");

    lock (lockObj)                     // same object that Java used for `synchronized (lock)`
    {
        CheckNotClosed();

        if (byteCount < 1)
            return 0;

        // If the remaining bytes in the buffer are enough, just move the position.
        if (end - pos >= byteCount)
        {
            pos += byteCount;
            return byteCount;
        }

        long read = end - pos;          // bytes already available
        pos = end;                      // consume the rest of the buffer

        while (read < byteCount)
        {
            // Try to fill the buffer again; -1 signals EOF (same as Java).
            if (FillBuf() == -1)
                return read;

            // After refilling, see if we now have enough bytes.
            if (end - pos >= byteCount - read)
            {
                pos += byteCount - read;
                return byteCount;
            }

            // Not enough yet – consume what we have and continue.
            read += (end - pos);
            pos = end;
        }

        return byteCount;
    }
}
