    jj_expentries.Clear();

    // Tokens that were expected at the point of error
    bool[] la1tokens = new bool[24];

    // If the current token kind is known, mark it as expected
    if (jj_kind >= 0)
    {
        la1tokens[jj_kind] = true;
        jj_kind = -1;
    }

    // Examine the look‑ahead sets (jj_la1) that were generated by the parser
    for (int i = 0; i < 10; i++)
    {
        if (jj_la1[i] == jj_gen)
        {
            for (int j = 0; j < 32; j++)
            {
                if ((jj_la1_0[i] & (1 << j)) != 0)
                {
                    la1tokens[j] = true;
                }
            }
        }
    }

    // Build the list of expected token sequences
    for (int i = 0; i < 24; i++)
    {
        if (la1tokens[i])
        {
            jj_expentry = new int[1];
            jj_expentry[0] = i;
            jj_expentries.Add(jj_expentry);
        }
    }

    // Prepare for error reporting
    jj_endpos = 0;
    jj_rescan_token();
    jj_add_error_token(0, 0);

    // Convert the List<int[]> into a plain two‑dimensional array
    int[][] exptokseq = new int[jj_expentries.Count][];
    for (int i = 0; i < jj_expentries.Count; i++)
    {
        exptokseq[i] = jj_expentries[i];
    }

    // Create and return the ParseException
