    private readonly FST _fst;
    private readonly FST.BytesReader _fstReader;
    private readonly int _rollBufferSize;
    private readonly PendingInput[] _futureInputs;
    private readonly PendingOutputs[] _futureOutputs;
    private readonly FST.Arc<object> _scratchArc;   // adjust generic type as needed

    public SynonymFilter(TokenStream input, SynonymMap synonyms, bool ignoreCase)
        : base(input)
    {
        _synonyms   = synonyms;
        _ignoreCase = ignoreCase;
        _fst        = synonyms.Fst;

        if (_fst == null)
        {
            throw new ArgumentException("fst must be non-null");
        }

        _fstReader       = _fst.GetBytesReader();
        _rollBufferSize  = 1 + synonyms.MaxHorizontalContext;
        _futureInputs    = new PendingInput[_rollBufferSize];
        _futureOutputs   = new PendingOutputs[_rollBufferSize];

        for (int pos = 0; pos < _rollBufferSize; pos++)
        {
            _futureInputs[pos]  = new PendingInput();
            _futureOutputs[pos] = new PendingOutputs();
        }

        _scratchArc = new FST.Arc<object>();
    }
}
