    field_1_color1 = BitConverter.ToInt32(data, pos + size);
    size += 4;
    field_2_color2 = BitConverter.ToInt32(data, pos + size);
    size += 4;
    field_3_color3 = BitConverter.ToInt32(data, pos + size);
    size += 4;
    field_4_color4 = BitConverter.ToInt32(data, pos + size);
    size += 4;

    bytesRemaining -= size;
    if (bytesRemaining != 0)
