public Note Call()
{
    CheckCallable();

    // Create an empty NoteMap
    var map = NoteMap.NewEmptyMap();
    RevCommit notesCommit = null;

    try
    {
        // Using statements ensure proper disposal of resources
        using (var walk = new RevWalk(repo))
        using (var inserter = repo.NewObjectInserter())
        {
            // Find the reference that holds the notes
            var @ref = repo.FindRef(notesRef);
            if (@ref != null)
            {
                // Parse the commit that contains the existing notes
                notesCommit = walk.ParseCommit(@ref.ObjectId);
                // Load the existing notes into the map
                map = NoteMap.Read(walk.ObjectReader, notesCommit);
            }

            // Add or replace the note for the given object id
            map.Set(id, message, inserter);

            // Write the updated notes map back to the repository
            CommitNoteMap(
                repo,
                notesRef,
                walk,
                map,
                notesCommit,
                inserter,
                "Notes added by 'git notes add'");

            // Return the newly added (or updated) note
            return map.GetNote(id);
        }
    }
    catch (IOException e)
    {
        // Wrap any I/O errors in a JGit‑specific exception
        throw new JGitInternalException(e.Message, e);
    }
}
