public string GetText(Interval interval) 
{
    int start = interval.a;
    int stop = interval.b;
    if (start < 0 || stop < 0) 
        return "";
    Fill();
    if (stop >= tokens.Count) 
        stop = tokens.Count - 1;
    StringBuilder buf = new StringBuilder();
    for (int i = start; i <= stop; i++) 
    {
        Token t = tokens[i];
        if (t.GetType() == Token.EOF) 
            break;
        buf.Append(t.GetText());
    }
    return buf.ToString();
}
