public void Reset(bool zeroFillBuffers, bool reuseFirst)
{
    if (bufferUpto != -1)
    {
        if (zeroFillBuffers)
        {
            for (int i = 0; i < bufferUpto; i++)
            {
                for (int j = 0; j < buffers[i].Length; j++)
                {
                    buffers[i][j] = 0;
                }
            }
            for (int j = 0; j < intUpto; j++)
            {
                buffers[bufferUpto][j] = 0;
            }
        }
        if (bufferUpto > 0 || !reuseFirst)
        {
            int offset = reuseFirst ? 1 : 0;
            allocator.RecycleIntBlocks(buffers, offset, 1 + bufferUpto);
            for (int i = offset; i <= bufferUpto; i++)
            {
                buffers[i] = null;
            }
        }
        if (reuseFirst)
        {
            bufferUpto = 0;
            intUpto = 0;
            intOffset = 0;
            buffer = buffers[0];
        }
        else
        {
            bufferUpto = -1;
            intUpto = INT_BLOCK_SIZE;
            intOffset = -INT_BLOCK_SIZE;
            buffer = null;
        }
    }
}
