    for (int i = 0; i < disjuncts.Length; i++)
    {
        Query subquery = disjuncts[i];
        if (subquery is BooleanQuery)
        {
            buffer.Append("(");
            buffer.Append(subquery.ToString(field));
            buffer.Append(")");
