public string Validate(string uri, int start, int end, string name)
{
    for (int i = start; i < end; )
    {
        char ch = uri[i];
        if ((ch >= 'a' && ch <= 'z') ||
            (ch >= 'A' && ch <= 'Z') ||
            (ch >= '0' && ch <= '9') ||
            IsRetained(ch))
        {
            i++;
        }
        else if (ch == '%')
        {
            if (i + 2 >= end)
            {
                throw new UriFormatException($"Incomplete % sequence in {name}", uri, i);
            }
            int d1 = HexToInt(uri[i + 1]);
            int d2 = HexToInt(uri[i + 2]);
            if (d1 == -1 || d2 == -1)
            {
                throw new UriFormatException($"Invalid % sequence: {uri.Substring(i, 3)} in {name}", uri, i);
            }
            i += 3;
        }
        else
        {
            throw new UriFormatException($"Illegal character in {name}", uri, i);
        }
    }
    return uri.Substring(start, end - start);
}

private int HexToInt(char c)
{
    if (c >= '0' && c <= '9')
    {
        return c - '0';
    }
    else if (c >= 'a' && c <= 'f')
    {
        return c - 'a' + 10;
    }
    else if (c >= 'A' && c <= 'F')
    {
        return c - 'A' + 10;
    }
    else
    {
        return -1;
    }
}

private bool IsRetained(char c)
{
