public LongsRef Next(int count)
{
    if (nextValues.Length < 0) throw new InvalidOperationException();
    if (count <= 0) throw new ArgumentException("Count must be greater than 0");
    if (nextValues.Offset + nextValues.Length > nextValues.longs.Length) 
        throw new InvalidOperationException();

    nextValues.Offset += nextValues.Length;
    int remaining = valueCount - position - 1;
    if (remaining <= 0) 
        throw new EndOfStreamException();

