public List<string> Call()
{
    CheckCallable();
    List<string> result = new List<string>();
    if (tags.IsNullOrEmpty())
        return result;
    try
    {
        SetCallable(false);
        foreach (var tagName in tags)
        {
            if (tagName == null)
                continue;
            Ref currentRef = repo.FindRef(tagName);
            if (currentRef == null)
                continue;
            string fullName = currentRef.Name;
            RefUpdate update = repo.UpdateRef(fullName);
            update.ForceUpdate = true;
            Result deleteResult = update.Delete();
            bool ok = true;
            switch (deleteResult)
            {
                case Result.IOFailure:
                case Result.LockFailure:
                case Result.Rejected:
                    ok = false;
                    break;
                default:
                    break;
            }
            if (ok)
            {
                result.Add(fullName);
            }
            else
            {
                throw new JGitInternalException(string.Format(JGitText.Get().DeleteTagUnexpectedResult, deleteResult.ToString()));
            }
        }
        return result;
    }
    catch (IOException ioe)
    {
        throw new JGitInternalException(ioe.Message, ioe);
    }
}
