```csharp
public List<string> Call()
{
    CheckCallable();
    var result = new List<string>();
    if (tags.Count == 0)
        return result;
    try
    {
        SetCallable(false);
        foreach (var tagName in tags)
        {
            if (tagName == null)
                continue;
            var currentRef = repo.FindRef(tagName);
            if (currentRef == null)
                continue;
            var fullName = currentRef.Name;
            var update = repo.UpdateRef(fullName);
            update.ForceUpdate = true;
            var deleteResult = update.Delete();
            var ok = true;
            switch (deleteResult)
            {
                case Result.IOFailure:
                case Result.LockFailure:
                case Result.Rejected:
                    ok = false;
                    break;
                default:
                    break;
            }
            if (ok)
            {
                result.Add(fullName);
            }
            else
            {
                throw new JGitInternalException(string.Format(JGitText.Get().DeleteTagUnexpectedResult, deleteResult));
            }
        }
        return result;
    }
    catch (IOException ioe)
    {
        throw new JGitInternalException(ioe.Message, ioe);
    }
}
