private static void WriteHex(System.Text.StringBuilder sb, uint value, int minLength, string prefix)
{
    sb.Append(prefix);
    for (int i = minLength - 1; i >= 0; i--)
    {
        uint digit = (value >> (i * 4)) & 0xF;
        sb.Append(digit.ToString("X"));
    }
}
```
