public static long PopAndNot(long[] arr1, long[] arr2, int wordOffset, int numWords)
{
    long popCount = 0;
    for (int i = wordOffset, end = wordOffset + numWords; i < end; ++i)
    {
        long value = arr1[i] & ~arr2[i];
