public static readonly int tagger(byte[] b, int ptr) 
{
    int sz = b.Length;
    if (ptr == 0)
        ptr += 48;
    while (ptr < sz) 
    {
        if (b[ptr] == '\n')
            return -1;
        int m = match(b, ptr, tagger);
        if (m >= 0)
            return m;
        ptr = nextLF(b, ptr);
    }
    return -1;
}
```

