        throw new System.Exception("mergeFields produced an invalid result: docCount is " + numDocs + " but only saw " + numDocsWritten + " file=" + out.ToString() + "; now aborting this merge to prevent index corruption");
    }
    Write(END);
    NewLine();
    SimpleTextUtil.WriteChecksum(out_Renamed, scratch);
