However, the `Math.nextUp` and `Math.nextAfter` functions are not directly available in C#. A more idiomatic C# translation would be:

```csharp
public DoubleRange(string label, double minIn, bool minInclusive, double maxIn, bool maxInclusive) : base(label)
{
    if (double.IsNaN(minIn))
    {
        throw new ArgumentException("min cannot be NaN");
    }
    if (!minInclusive)
    {
        minIn = NextDouble(minIn, true);
    }
    if (double.IsNaN(maxIn))
    {
        throw new ArgumentException("max cannot be NaN");
    }
    if (!maxInclusive)
    {
        maxIn = NextDouble(maxIn, false);
    }
    if (minIn > maxIn)
    {
        FailNoMatch();
    }
    this.min = minIn;
    this.max = maxIn;
}

private static double NextDouble(double value, bool up)
{
    long bits = BitConverter.DoubleToInt64Bits(value);
    if (up)
    {
        bits++;
    }
    else
    {
        bits--;
    }
    return BitConverter.Int64BitsToDouble(bits);
}
