private class CharArrayComparer : IEqualityComparer<char[]>
{
    private readonly bool _ignoreCase;

    public CharArrayComparer(bool ignoreCase)
    {
        _ignoreCase = ignoreCase;
    }

    public bool Equals(char[] x, char[] y)
    {
        if (x.Length != y.Length) return false;
        for (int i = 0; i < x.Length; i++)
        {
            if (_ignoreCase)
            {
                if (char.ToLower(x[i]) != char.ToLower(y[i])) return false;
            }
            else
            {
                if (x[i] != y[i]) return false;
            }
        }
        return true;
    }

    public int GetHashCode(char[] obj)
    {
        unchecked
        {
            int hash = 17;
            foreach (char c in obj)
            {
                hash = hash * 23 + (_ignoreCase ? char.ToLower(c).GetHashCode() : c.GetHashCode());
            }
            return hash;
        }
    }
}
