public string GetText(Interval interval) 
{
    if (interval.a < 0 || interval.b < interval.a - 1) 
    {
        throw new System.ArgumentException("invalid interval");
    }
    int bufferStartIndex = GetBufferStartIndex();
    if (n > 0 && data[n - 1] == char.MaxValue) 
    {
        if (interval.a + interval.Length() > bufferStartIndex + n) 
        {
            throw new System.ArgumentException("the interval extends past the end of the stream");
        }
    }
    if (interval.a < bufferStartIndex || interval.b >= bufferStartIndex + n) 
    {
        throw new System.NotSupportedException("interval " + interval + " outside buffer: " + bufferStartIndex + ".." + (bufferStartIndex + n - 1));
    }
    int i = interval.a - bufferStartIndex;
    return new string(data, i, interval.Length());
}
