public ICollection<RevCommit> Call()
{
    CheckCallable();
    try
    {
        if (Repo.LookupReference(Constants.R_STASH) == null)
            return new List<RevCommit>();
    }
    catch (IOException e)
    {
        throw new InvalidRefNameException(string.Format(JGitText.get().cannotRead, Constants.R_STASH), e);
    }
    var reflogCmd = new ReflogCommand(Repo);
    reflogCmd.SetRef(Constants.R_STASH);
    var stashEntries = reflogCmd.Call();
    if (stashEntries.Count == 0)
        return new List<RevCommit>();
    var stashCommits = new List<RevCommit>(stashEntries.Count);
    using (var walk = new RevWalk(Repo))
    {
        foreach (var entry in stashEntries)
        {
            try
            {
                stashCommits.Add(walk.ParseCommit(entry.NewId));
            }
            catch (IOException e)
            {
                throw new JGitInternalException(string.Format(JGitText.get().cannotReadCommit, entry.NewId), e);
            }
        }
    }
    return stashCommits;
}
