public void Reset(bool zeroFillBuffers, bool reuseFirst)
{
    if (bufferUpto != -1)
    {
        if (zeroFillBuffers)
        {
            for (int i = 0; i < bufferUpto; i++)
            {
                Array.Clear(buffers[i], 0, buffers[i].Length);
            }
            Array.Clear(buffers[bufferUpto], 0, intUpto);
        }
        if (bufferUpto > 0 || !reuseFirst)
        {
            int offset = reuseFirst ? 1 : 0;
            allocator.RecycleIntBlocks(buffers, offset, 1 + bufferUpto);
            Array.Clear(buffers, offset, bufferUpto + 1 - offset);
        }
        if (reuseFirst)
        {
            bufferUpto = 0;
            intUpto = 0;
            intOffset = 0;
            buffer = buffers[0];
        }
        else
        {
            bufferUpto = -1;
            intUpto = INT_BLOCK_SIZE;
            intOffset = -INT_BLOCK_SIZE;
            buffer = null;
        }
    }
}
