    var mergeScheduler = config.Get("merge.scheduler", "Lucene.Net.Index.ConcurrentMergeScheduler");
    if (mergeScheduler.Equals(typeof(NoMergeScheduler).AssemblyQualifiedName, StringComparison.Ordinal))
    {
        iwConf.MergeScheduler = NoMergeScheduler.Instance;
    }
    else
    {
        try
        {
            var mergeSchedulerType = Type.GetType(mergeScheduler);
            if (mergeSchedulerType != null && typeof(MergeScheduler).IsAssignableFrom(mergeSchedulerType))
            {
                iwConf.MergeScheduler = (MergeScheduler)Activator.CreateInstance(mergeSchedulerType);
            }
        }
        catch (Exception e)
        {
            // Handle the exception or ignore it, similar to the original Java code.
        }
    }

    return iwConf;
