public long Skip(long byteCount)
{
    if (byteCount < 0)
    {
        throw new ArgumentException("byteCount < 0: " + byteCount);
    }
    lock (lockObj)
    {
        CheckNotClosed();
        if (byteCount < 1)
        {
            return 0;
        }
        if (end - pos >= byteCount)
        {
            pos += byteCount;
            return byteCount;
        }
        long read = end - pos;
        pos = end;
        while (read < byteCount)
        {
            if (FillBuf() == -1)
            {
                return read;
            }
            if (end - pos >= byteCount - read)
            {
                pos += byteCount - read;
                return byteCount;
            }
            read += (end - pos);
            pos = end;
        }
        return byteCount;
    }
}
