    System.Diagnostics.Debug.Assert(toFree <= count);
    var index = nextWrite - count;
    if (index < 0) {
        index += positions.Length;
    }
    for (var i = 0; i < toFree; i++) {
        if (index == positions.Length) {
            index = 0;
        }
        positions[index].Reset();
        index++;
    }
    count -= toFree;
}
