public ICollection<RevCommit> Call()
{
    CheckCallable();
    try
    {
        if (repo.ExactRef(Constants.R_STASH) == null)
            return new List<RevCommit>();
    }
    catch (IOException e)
    {
        throw new InvalidRefNameException(string.Format(JGitText.Get().cannotRead, Constants.R_STASH), e);
    }

    var refLog = new ReflogCommand(repo);
    refLog.SetRef(Constants.R_STASH);
    var stashEntries = refLog.Call();

    if (stashEntries.IsEmpty())
        return new List<RevCommit>();

    var stashCommits = new List<RevCommit>(stashEntries.Count);

    using (var walk = new RevWalk(repo))
    {
        foreach (var entry in stashEntries)
        {
            try
            {
                stashCommits.Add(walk.ParseCommit(entry.GetNewId()));
            }
            catch (IOException e)
            {
                throw new JGitInternalException(string.Format(JGitText.Get().cannotReadCommit, entry.GetNewId()), e);
            }
        }
    }

    return stashCommits;
}
