public CharsRef Common(CharsRef output1, CharsRef output2)
{
    System.Diagnostics.Debug.Assert(output1 != null);
    System.Diagnostics.Debug.Assert(output2 != null);

    int pos1 = output1.Offset;
    int pos2 = output2.Offset;
    int stopAt1 = pos1 + Math.Min(output1.Length, output2.Length);

    while (pos1 < stopAt1)
    {
        if (output1.Chars[pos1] != output2.Chars[pos2])
        {
            break;
        }
        pos1++;
        pos2++;
    }

    if (pos1 == output1.Offset)
    {
        return NO_OUTPUT;
    }
    else if (pos1 == output1.Offset + output1.Length)
    {
        return output1;
    }
    else if (pos2 == output2.Offset + output2.Length)
    {
        return output2;
    }
    else
    {
        return new CharsRef(output1.Chars, output1.Offset, pos1 - output1.Offset);
    }
}
