public Collection<RevCommit> call() throws GitAPIException, InvalidRefNameException {
    checkCallable();
    try {
        if (repo.exactRef(Constants.R_STASH) == null)
            return Collections.emptyList();
    } catch (IOException e) {
        throw new InvalidRefNameException(MessageFormat.format(JGitText.get().cannotRead, Constants.R_STASH), e);
    }
    ReflogCommand refLog = new ReflogCommand(repo);
    refLog.setRef(Constants.R_STASH);
    Collection<ReflogEntry> stashEntries = refLog.call();
    if (stashEntries.isEmpty())
        return Collections.emptyList();
    List<RevCommit> stashCommits = new ArrayList<>(stashEntries.size());
    try (RevWalk walk = new RevWalk(repo)) {
        foreach (ReflogEntry entry in stashEntries) {
            try {
                stashCommits.add(walk.parseCommit(entry.getNewId()));
            } catch (IOException e) {
                throw new JGitInternalException(MessageFormat.format(JGitText.get().cannotReadCommit, entry.getNewId()), e);
            }
        }
    }
    return stashCommits;
}
