public void reset(bool zeroFillBuffers, bool reuseFirst)
{
    if (bufferUpto != -1)
    {
        if (zeroFillBuffers)
        {
            for (int i = 0; i < bufferUpto; i++)
            {
                Array.Fill(buffers[i], 0);
            }
            Array.Fill(buffers[bufferUpto], 0, intUpto, 0);
        }

        if (bufferUpto > 0 || !reuseFirst)
        {
            int offset = reuseFirst ? 1 : 0;
            allocator.recycleIntBlocks(buffers, offset, 1 + bufferUpto);
            Array.Fill(buffers, (byte[])null, offset, bufferUpto + 1);
        }

        if (reuseFirst)
        {
            bufferUpto = 0;
            intUpto = 0;
            intOffset = 0;
            buffer = buffers[0];
        }
        else
        {
            bufferUpto = -1;
            intUpto = INT_BLOCK_SIZE;
            intOffset = -INT_BLOCK_SIZE;
            buffer = null;
        }
    }
}
