public List<string> Call()
{
    CheckCallable();
    List<string> result = new List<string>();
    if (tags.Count == 0)
        return result;

    try
    {
        SetCallable(false);
        foreach (string tagName in tags)
        {
            if (tagName == null)
                continue;

            Ref currentRef = repo.FindRef(tagName);
            if (currentRef == null)
                continue;

            string fullName = currentRef.GetName();
            RefUpdate update = repo.UpdateRef(fullName);
            update.SetForceUpdate(true);
            Result deleteResult = update.Delete();
            bool ok = true;

            switch (deleteResult)
            {
                case Result.IO_FAILURE:
                case Result.LOCK_FAILURE:
                case Result.REJECTED:
                    ok = false;
                    break;
                default:
                    break;
            }

            if (ok)
            {
                result.Add(fullName);
            }
            else
            {
                throw new JGitInternalException(MessageFormat.Format(JGitText.Get().DeleteTagUnexpectedResult, deleteResult.Name()));
            }
        }
        return result;
    }
    catch (IOException ioe)
    {
        throw new JGitInternalException(ioe.Message, ioe);
    }
}
